  1→import { useCallback, useEffect, useRef, useState } from 'react';
  2→import { useNavigate } from 'react-router-dom';
  3→import { useCoreKitAuth } from '../lib/web3auth/hooks';
  4→import { useCoreKit } from '../lib/web3auth/core-kit-provider';
  5→import { authApi } from '../lib/api/auth';
  6→import { vaultApi } from '../lib/api/vault';
  7→import { useAuthStore } from '../stores/auth.store';
  8→import { useVaultStore } from '../stores/vault.store';
  9→import { useDeviceRegistryStore } from '../stores/device-registry.store';
 10→import { clearAllUserStores } from '../lib/clear-user-stores';
 11→import {
 12→  initializeVault,
 13→  encryptVaultKeys,
 14→  decryptVaultKeys,
 15→  deriveIpnsName,
 16→  hexToBytes,
 17→  bytesToHex,
 18→} from '@cipherbox/crypto';
 19→import { getOrCreateDeviceIdentity } from '../lib/device/identity';
 20→import { detectDeviceInfo } from '../lib/device/info';
 21→import { initializeOrSyncRegistry } from '../services/device-registry.service';
 22→import { initializeBin } from '../services/bin.service';
 23→import { useBinStore } from '../stores/bin.store';
 24→import { vaultControllerGetConfig } from '../api/vault/vault';
 25→
 26→export function useAuth() {
 27→  const navigate = useNavigate();
 28→  const {
 29→    isLoggedIn: coreKitLoggedIn,
 30→    isInitialized: coreKitInitialized,
 31→    isRequiredShare,
 32→    loginWithGoogle: coreKitLoginGoogle,
 33→    loginWithEmailOtp: coreKitLoginEmail,
 34→    loginWithWallet: coreKitLoginWallet,
 35→    getVaultKeypair,
 36→    getPublicKeyHex,
 37→    logout: coreKitLogout,
 38→  } = useCoreKitAuth();
 39→  const { syncStatus } = useCoreKit();
 40→  const {
 41→    accessToken,
 42→    isAuthenticated,
 43→    lastAuthMethod,
 44→    userEmail,
 45→    setAccessToken,
 46→    setLastAuthMethod,
 47→    setUserEmail,
 48→    setVaultKeypair,
 49→  } = useAuthStore();
 50→
 51→  const [isLoggingIn, setIsLoggingIn] = useState(false);
 52→  const [isLoggingOut, setIsLoggingOut] = useState(false);
 53→  const restoringRef = useRef(false);
 54→
 55→  // Stable refs for functions used in the session restoration effect.
 56→  // This prevents the effect from re-firing when function references change.
 57→  const initializeOrLoadVaultRef = useRef<(() => Promise<void>) | null>(null);
 58→  const coreKitLogoutRef = useRef<(() => Promise<void>) | null>(null);
 59→
 60→  // Pending auth state for REQUIRED_SHARE flow.
 61→  // Stored in Zustand (not useState) so the state is shared across all
 62→  // useAuth() hook instances — Login.tsx sets it, useDeviceApproval reads it
 63→  // via its own useAuth() call.
 64→  const pendingAuthMethod = useAuthStore((s) => s.pendingAuthMethod);
 65→  const setPendingAuth = useAuthStore((s) => s.setPendingAuth);
 66→
 67→  const isLoading = !coreKitInitialized || isLoggingIn || isLoggingOut;
 68→
 69→  // Get vault store actions
 70→  const setVaultKeys = useVaultStore((state) => state.setVaultKeys);
 71→
 72→  /**
 73→   * Initialize vault for new users or load existing vault keys.
 74→   * Called after successful backend authentication.
 75→   * Uses Core Kit's getVaultKeypair() instead of PnP provider.
 76→   */
 77→  const initializeOrLoadVault = useCallback(async (): Promise<void> => {
 78→    // Get user's secp256k1 keypair from Core Kit TSS export
 79→    const userKeypair = await getVaultKeypair();
 80→
 81→    if (!userKeypair) {
 82→      throw new Error('Failed to get vault keypair from Core Kit');
 83→    }
 84→
 85→    // Store keypair in auth store for crypto operations
 86→    setVaultKeypair(userKeypair);
 87→
 88→    try {
 89→      // Try to fetch existing vault
 90→      const existingVault = await vaultApi.getVault();
 91→
 92→      // Store TEE keys if available
 93→      if (existingVault.teeKeys) {
 94→        useAuthStore.getState().setTeeKeys(existingVault.teeKeys);
 95→      }
 96→
 97→      // Vault exists - decrypt keys and load into store
 98→      // decryptVaultKeys derives the IPNS public key internally from the decrypted private key
 99→      const decryptedVault = await decryptVaultKeys(
100→        {
101→          encryptedRootFolderKey: hexToBytes(existingVault.encryptedRootFolderKey),
102→          encryptedIpnsPrivateKey: hexToBytes(existingVault.encryptedRootIpnsPrivateKey),
103→        },
104→        userKeypair.privateKey
105→      );
106→
107→      setVaultKeys({
108→        rootFolderKey: decryptedVault.rootFolderKey,
109→        rootIpnsKeypair: decryptedVault.rootIpnsKeypair,
110→        rootIpnsName: existingVault.rootIpnsName,
111→        vaultId: existingVault.id,
112→      });
113→    } catch (error) {
114→      const is404 = (error as { response?: { status?: number } })?.response?.status === 404;
115→
116→      if (is404) {
117→        // New user - initialize vault
118→        console.log(
119→          '[Auth] New user on Core Kit. If migrating from PnP, vault re-initialization may be needed.'
120→        );
121→        const newVault = await initializeVault(userKeypair.privateKey);
122→        const encryptedVault = await encryptVaultKeys(newVault, userKeypair.publicKey);
123→        const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);
124→
125→        const storedVault = await vaultApi.initVault({
126→          ownerPublicKey: bytesToHex(userKeypair.publicKey),
127→          encryptedRootFolderKey: bytesToHex(encryptedVault.encryptedRootFolderKey),
128→          encryptedRootIpnsPrivateKey: bytesToHex(encryptedVault.encryptedIpnsPrivateKey),
129→          rootIpnsName,
130→        });
131→
132→        if (storedVault.teeKeys) {
133→          useAuthStore.getState().setTeeKeys(storedVault.teeKeys);
134→        }
135→
136→        setVaultKeys({
137→          rootFolderKey: newVault.rootFolderKey,
138→          rootIpnsKeypair: newVault.rootIpnsKeypair,
139→          rootIpnsName,
140→          vaultId: storedVault.id,
141→          isNewVault: true,
142→        });
143→      } else {
144→        console.error('[useAuth] Failed to load vault:', error);
145→        throw error;
146→      }
147→    }
148→
149→    // Non-blocking device registry initialization (fire-and-forget)
150→    // Placed after vault load so registry failures never block login
151→    void (async () => {
152→      try {
153→        const deviceKeypair = await getOrCreateDeviceIdentity();
154→        const deviceInfo = detectDeviceInfo();
155→        const result = await initializeOrSyncRegistry({
156→          userPrivateKey: userKeypair.privateKey,
157→          userPublicKey: userKeypair.publicKey,
158→          deviceKeypair,
159→          deviceInfo: { ...deviceInfo, ipHash: '' },
160→        });
161→        if (result) {
162→          useDeviceRegistryStore
163→            .getState()
164→            .setRegistry(result.registry, result.ipnsName, deviceKeypair.deviceId);
165→        }
166→      } catch (error) {
167→        console.error('[Auth] Device registry init failed (non-blocking):', error);
168→      }
169→    })();
170→
171→    // Non-blocking bin initialization (fire-and-forget)
172→    void (async () => {
173→      try {
174→        await initializeBin({
175→          userPrivateKey: userKeypair.privateKey,
176→          userPublicKey: userKeypair.publicKey,
177→        });
178→      } catch (error) {
179→        console.error('[Auth] Bin initialization failed (non-blocking):', error);
180→      }
181→    })();
182→
183→    // Non-blocking: fetch retention config from API
184→    void (async () => {
185→      try {
186→        const config = await vaultControllerGetConfig();
187→        if (config.recycleBinRetentionDays != null) {
188→          useBinStore.getState().setRetentionDays(config.recycleBinRetentionDays);
189→        }
190→      } catch (error) {
191→        console.error('[Auth] Failed to fetch vault config (non-blocking):', error);
192→      }
193→    })();
194→  }, [getVaultKeypair, setVaultKeypair, setVaultKeys]);
195→
196→  /**
197→   * Complete backend authentication after Core Kit login.
198→   * Sends the CipherBox-issued JWT (which we used for Core Kit loginWithJWT)
199→   * to the backend with loginType 'corekit'. The backend verifies it against
200→   * its own JWKS since CipherBox is the identity provider.
201→   */
202→  const completeBackendAuth = useCallback(
203→    async (authMethod: string, cipherboxJwt: string): Promise<void> => {
204→      // 1. Get real publicKey from Core Kit TSS export
205→      const publicKey = await getPublicKeyHex();
206→      if (!publicKey) {
207→        throw new Error('Failed to get publicKey from Core Kit');
208→      }
209→
210→      // publicKey available for debugging via DevTools if needed
211→
212→      // 2. Authenticate with CipherBox backend
213→      // Backend verifies our CipherBox JWT and resolves placeholder publicKey
214→      const response = await authApi.login({
215→        idToken: cipherboxJwt,
216→        publicKey,
217→        loginType: 'corekit',
218→      });
219→
220→      // 3. Store access token (refresh token in HTTP-only cookie)
221→      setAccessToken(response.accessToken);
222→
223→      // 4. Remember auth method for UX
224→      setLastAuthMethod(authMethod);
225→
226→      // 5. Initialize or load vault
227→      await initializeOrLoadVault();
228→    },
229→    [getPublicKeyHex, setAccessToken, setLastAuthMethod, initializeOrLoadVault]
230→  );
231→
232→  /**
233→   * Complete the login flow after REQUIRED_SHARE is resolved.
234→   * Called after inputFactorKey() succeeds (from recovery phrase or cross-device approval).
235→   * Uses the stored pendingCipherboxJwt to call completeBackendAuth with the REAL publicKey
236→   * (since Core Kit is now LOGGED_IN), then navigates to /files.
237→   */
238→  const completeRequiredShare = useCallback(async (): Promise<void> => {
239→    // Read directly from Zustand store to get fresh values — this callback
240→    // may be called from useDeviceApproval's useAuth() instance, so we
241→    // can't rely on closure-captured selector values.
242→    const { pendingCipherboxJwt: jwt, pendingAuthMethod: method } = useAuthStore.getState();
243→
244→    if (!jwt || !method) {
245→      throw new Error('No pending auth info for REQUIRED_SHARE completion');
246→    }
247→
248→    // Core Kit should now be LOGGED_IN after inputFactorKey()
249→    // Complete backend auth with the REAL publicKey (replaces the placeholder session)
250→    await completeBackendAuth(method, jwt);
251→
252→    // NOW sync Core Kit React state to LOGGED_IN.
253→    // We deliberately delayed this from inputFactorKey() to prevent the session
254→    // restoration effect from firing before backend auth completed.
255→    // At this point isAuthenticated is true (from completeBackendAuth -> setAccessToken),
256→    // so the session restore guard (coreKitLoggedIn && !isAuthenticated) won't trigger.
257→    syncStatus();
258→
259→    // Clear pending state
260→    setPendingAuth(null, null);
261→
262→    // Navigate to files
263→    navigate('/files');
264→  }, [completeBackendAuth, syncStatus, setPendingAuth, navigate]);
265→
266→  /**
267→   * Login with Google OAuth token.
268→   * Flow: Google idToken -> CipherBox backend -> CipherBox JWT ->
269→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
270→   */
271→  const loginWithGoogle = useCallback(
272→    async (googleIdToken: string): Promise<void> => {
273→      if (isLoggingIn) return;
274→      setIsLoggingIn(true);
275→      try {
276→        // 1. Core Kit login via CipherBox identity provider
277→        const {
278→          cipherboxJwt,
279→          email,
280→          userId,
281→          status: coreKitStatus,
282→        } = await coreKitLoginGoogle(googleIdToken);
283→
284→        if (coreKitStatus === 'required_share') {
285→          // MFA enabled but device factor missing.
286→          // Store pending auth info for later completion after factor input.
287→          setPendingAuth(cipherboxJwt, 'google');
288→
289→          // Obtain temporary backend access token so the new device can
290→          // call bulletin board API endpoints (device-approval/*).
291→          // Uses placeholder publicKey since Core Kit is in REQUIRED_SHARE
292→          // state and we can't export the TSS key yet.
293→          const tempLoginResponse = await authApi.login({
294→            idToken: cipherboxJwt,
295→            publicKey: `pending-core-kit-${userId}`,
296→            loginType: 'corekit',
297→          });
298→          setAccessToken(tempLoginResponse.accessToken);
299→
300→          if (email) {
301→            setUserEmail(email);
302→          }
303→
304→          // Do NOT call completeBackendAuth() or navigate('/files')
305→          // The component tree will see isRequiredShare === true and
306→          // render recovery/approval UI.
307→          return;
308→        }
309→
310→        // Normal path: Core Kit logged in, proceed as before
311→        // 2. Complete backend auth + vault init
312→        await completeBackendAuth('google', cipherboxJwt);
313→
314→        // 3. Store email for UI display (returned from identity endpoint)
315→        if (email) {
316→          setUserEmail(email);
317→        }
318→
319→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
320→      } catch (error) {
321→        console.error('[useAuth] Google login failed:', error);
322→        throw error;
323→      } finally {
324→        setIsLoggingIn(false);
325→      }
326→    },
327→    [isLoggingIn, coreKitLoginGoogle, completeBackendAuth, setAccessToken, setUserEmail]
328→  );
329→
330→  /**
331→   * Login with Email OTP.
332→   * Flow: email+otp -> CipherBox backend -> CipherBox JWT ->
333→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
334→   */
335→  const loginWithEmail = useCallback(
336→    async (email: string, otp: string): Promise<void> => {
337→      if (isLoggingIn) return;
338→      setIsLoggingIn(true);
339→      try {
340→        // 1. Core Kit login via CipherBox identity provider
341→        const { cipherboxJwt, userId, status: coreKitStatus } = await coreKitLoginEmail(email, otp);
342→
343→        if (coreKitStatus === 'required_share') {
344→          setPendingAuth(cipherboxJwt, 'email');
345→
346→          const tempLoginResponse = await authApi.login({
347→            idToken: cipherboxJwt,
348→            publicKey: `pending-core-kit-${userId}`,
349→            loginType: 'corekit',
350→          });
351→          setAccessToken(tempLoginResponse.accessToken);
352→          setUserEmail(email);
353→          return;
354→        }
355→
356→        // Normal path
357→        await completeBackendAuth('email', cipherboxJwt);
358→        setUserEmail(email);
359→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
360→      } catch (error) {
361→        console.error('[useAuth] Email login failed:', error);
362→        throw error;
363→      } finally {
364→        setIsLoggingIn(false);
365→      }
366→    },
367→    [isLoggingIn, coreKitLoginEmail, completeBackendAuth, setAccessToken, setUserEmail]
368→  );
369→
370→  /**
371→   * Login with Wallet (SIWE).
372→   * Flow: Wallet connects + signs SIWE message -> backend verifies ->
373→   * CipherBox JWT -> Core Kit loginWithJWT -> backend /auth/login (corekit type)
374→   */
375→  const loginWithWallet = useCallback(
376→    async (cipherboxJwt: string, userId: string): Promise<void> => {
377→      if (isLoggingIn) return;
378→      setIsLoggingIn(true);
379→      try {
380→        // 1. Core Kit login via CipherBox identity provider
381→        const { status: coreKitStatus } = await coreKitLoginWallet(cipherboxJwt, userId);
382→
383→        if (coreKitStatus === 'required_share') {
384→          setPendingAuth(cipherboxJwt, 'wallet');
385→
386→          const tempLoginResponse = await authApi.login({
387→            idToken: cipherboxJwt,
388→            publicKey: `pending-core-kit-${userId}`,
389→            loginType: 'corekit',
390→          });
391→          setAccessToken(tempLoginResponse.accessToken);
392→          return;
393→        }
394→
