  }

  @Delete(':shareId/complete-rotation')
  @HttpCode(HttpStatus.NO_CONTENT)
  @ApiOperation({
    summary: 'Complete key rotation',
    description:
      'Hard-delete a revoked share after the sharer has rotated the folder key. ' +
