      revokeShare: jest.fn(),
      hideShare: jest.fn(),
      lookupUserByPublicKey: jest.fn(),
      getPendingRotations: jest.fn(),
      completeRotation: jest.fn(),
      updateShareEncryptedKey: jest.fn(),
    };

    const module: TestingModule = await Test.createTestingModule({
      controllers: [SharesController],
